import Foundation

/// The protected thing.
public let SECRET_COLUMNS = ["token"]

/// The chokepoint: the one way a row leaves without its secrets.
public func seal(_ row: [String: String]) -> [String: String] {
    var out = row
    for column in SECRET_COLUMNS {
        out[column] = nil
    }
    return out
}

